import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = [[-1] + [row["version"] for row in packages[name]] for name in names]
    best_key = None
    best = None

    for values in product(*options):
        chosen = dict(zip(names, values))
        installed = {n for n, v in chosen.items() if v != -1}
        if any(n not in installed or not low <= chosen[n] <= high
               for n, (low, high) in data["roots"].items()):
            continue
        if any(v in blocked.get(n, []) or (n in pins and pins[n] != v)
               for n, v in chosen.items() if v != -1):
            continue
        edges = {n: [] for n in installed}
        valid = True
        for n in installed:
            row = next(r for r in packages[n] if r["version"] == chosen[n])
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in installed or not dep["min"] <= chosen[target] <= dep["max"]:
                    valid = False
                    break
                edges[n].append(target)
            if not valid:
                break
        if not valid:
            continue
        reachable = set()
        stack = list(data["roots"])
        while stack:
            n = stack.pop()
            if n in reachable or n not in installed:
                continue
            reachable.add(n)
            stack.extend(edges[n])
        if reachable != installed:
            continue
        state = {}
        def visit(n):
            if state.get(n) == 1:
                return False
            if state.get(n) == 2:
                return True
            state[n] = 1
            if any(not visit(m) for m in edges[n]):
                return False
            state[n] = 2
            return True
        if not all(visit(n) for n in installed):
            continue
        ordered = sorted(names, reverse=(name_order == "descending"))
        key = tuple(chosen[n] for n in ordered)
        if best_key is None or (key < best_key if preference == "minimum" else key > best_key):
            best_key = key
            best = {n: chosen[n] for n in installed}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _dep(data, preference, order):
    return dependency_solver(data, preference, order)


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)
    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(num, den):
        return (num + den // 2) // den if mode == "half_up" else num // den

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def schedule(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    candidates = [j for j in jobs if j["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(candidates, k):
        ids = {j["id"] for j in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for j in subset:
            counts[j["group"]] = counts.get(j["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(j["value"] for j in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bit.get(start, 0)
    initial = (start, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], initial)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, state = heapq.heappop(queue)
        if distances.get(state) != time:
            continue
        node, mask, left = state
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], left)]
            if left:
                choices.append((max(2, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                new_state = (nxt, mask | bit.get(nxt, 0), remaining)
                if arrival < distances.get(new_state, float("inf")):
                    distances[new_state] = arrival
                    heapq.heappush(queue, (arrival, new_state))
    return {"arrival": None}


